    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // When k is even and r == k/2
            if (remainderCount[r] % 2 != 0) {
