    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 with zero cost or step 0 with its cost, choose the cheaper
        return 0;
    }
    // Base cases for first two steps
    int prevPrev = cost[0]; // min cost to reach step 0
    int prev = cost[1];     // min cost to reach step 1
    if (n == 2) {
        return Math.min(prevPrev, prev);
    }
    // Iterate from step 2 to step n-1
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = current;
    }
    // The top can be reached from either the last step or the second-to-last step
    return Math.min(prev, prevPrev);
}

