public boolean hasAllCodes(String s, int k) {
    // Basic input validation
    if (s == null || k < 0) {
        return false;
    }
    // A zero-length binary string is trivially present
    if (k == 0) {
        return true;
    }

    int n = s.length();
    // If the pattern length exceeds the string length, it's impossible
    if (k > n) {
        return false;
    }

    int totalCodes = 1 << k;                 // Total binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int mask = 0;
    int maskAll = (1 << k) - 1;
    int seenCount = 0;

    for (int i = 0; i < n; i++) {
        int bit = s.charAt(i) - '0';         // 0 or 1
        mask = ((mask << 1) & maskAll) | bit;
        if (i >= k - 1) {                    // We have a full window
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true;             // All codes found early
                }
            }
        }
    }
    return false;                            // Not all codes were encountered
}

