public int minInsertions(String s) {
    // Handle null or empty input
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int openNeeded = 0;   // Count of unmatched '(' that need a corresponding ')'
    int insertions = 0;   // Count of inserted '(' needed for unmatched ')'

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            openNeeded++;
        } else if (c == ')') {
            if (openNeeded > 0) {
                openNeeded--;  // Match with a previous '('
            } else {
                // No matching '(' available, need to insert one
                insertions++;
            }
        } else {
            // The problem statement guarantees only '(' and ')'
            // If an unexpected character appears, we can ignore or handle as error.
            // Here we choose to ignore to be defensive.
        }
    }
    // After processing all characters, any remaining openNeeded requires closing ')'
    insertions += openNeeded;
    return insertions;
}

public int minOperations(int n) {
