        throw new IllegalArgumentException("n is too large to compute in int");
    }
    long result;
    if ((n & 1) == 0) { // even
        int half = n / 2;
        result = (long) half * half;
    } else { // odd
        int q = (n - 1) / 2;
        result = (long) q * (q + 1);
    }
    return (int) result;
}

