        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int limit = (int) Math.sqrt(n);
    int[] small = new int[limit + 1];
    int smallSize = 0;
    int[] large = new int[limit + 1];
    int largeSize = 0;
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            small[smallSize++] = i;
            int complement = n / i;
            if (complement != i) {
                large[largeSize++] = complement;
            }
        }
    }
    int totalFactors = smallSize + largeSize;
    if (k > totalFactors) {
        return -1;
    }
    if (k <= smallSize) {
        return small[k - 1];
    } else {
        int offset = k - smallSize;
        return large[largeSize - offset];
    }
}

