private int backtrack(int idx, java.util.HashSet<String> used, String s) {
    if (idx == s.length()) {
        return used.size();
    }
    int max = 0;
    for (int i = idx + 1; i <= s.length(); i++) {
        String substr = s.substring(idx, i);
        if (!used.contains(substr)) {
            used.add(substr);
            max = Math.max(max, backtrack(i, used, s));
            used.remove(substr);
        }
    }
    return max;
}

